"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found


class CustomerInsightsController:
    def __init__(self, service: OrderService, customers: CustomerService) -> None:
        self._service = service
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the same totals ``handle_get`` reports."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        history: list[dict[str, Any]] = [
            {"order_id": summary.order.order_id,
             "status": summary.order.status,
             "total_cents": summary.total_cents}
            for summary in (self._service.summarize(order) for order in reversed(orders))
        ]
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders that are not cancelled, at the history totals."""
        try:
            count, total = self._lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id,
                              "order_count": count,
                              "lifetime_value_cents": total})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value, highest first, excluding zero-value customers."""
        if type(limit) is not int or limit < 1:
            return bad_request(InvalidRequest("limit must be a positive integer"))
        ranked = []
        for customer in self._customers.list_all():
            _, total = self._lifetime_value(customer.customer_id)
            if total > 0:
                ranked.append((total, customer.customer_id, customer.name))
        ranked.sort(key=lambda row: (-row[0], row[1]))
        return Response(200, {"customers": [
            {"customer_id": cid, "name": name, "lifetime_value_cents": total}
            for total, cid, name in ranked[:limit]
        ]})

    def _lifetime_value(self, customer_id: str) -> tuple[int, int]:
        """(number of non-cancelled orders, sum of their totals). Raises CustomerNotFound."""
        orders = self._service.list_for_customer(customer_id)
        active = [order for order in orders if order.status != "cancelled"]
        return len(active), sum(self._service.summarize(order).total_cents for order in active)

